// src/systems/timers.ts
class WorldLoopTimerManager {
  world;
  timeouts = new Map;
  intervals = new Map;
  nextId = 1;
  constructor(world) {
    this.world = world;
    this.world.loop.on(iPQ.TICK_END, ({ worldLoop }) => {
      this.processTick(worldLoop.currentTick);
    });
  }
  processTick(currentTick) {
    for (const [id2, entry] of Array.from(this.timeouts.entries())) {
      if (currentTick >= entry.targetTick) {
        try {
          entry.callback();
        } catch (error) {
          console.error(`[Timers] Error in timeout ${id2}:`, error);
        }
        this.timeouts.delete(id2);
      }
    }
    for (const [id2, entry] of Array.from(this.intervals.entries())) {
      if (currentTick >= entry.nextTick) {
        try {
          entry.callback();
        } catch (error) {
          console.error(`[Timers] Error in interval ${id2}:`, error);
        }
        entry.nextTick = currentTick + entry.intervalTicks;
      }
    }
  }
  msToTicks(ms) {
    const tickDurationMs = this.world.loop.timestepS * 1000;
    return Math.max(1, Math.ceil(ms / tickDurationMs));
  }
  setTimeout(delayMs, callback) {
    const ticks = this.msToTicks(delayMs);
    const id2 = this.nextId++;
    const targetTick = this.world.loop.currentTick + ticks;
    this.timeouts.set(id2, { targetTick, callback });
    return id2;
  }
  clearTimeout(id2) {
    this.timeouts.delete(id2);
  }
  setInterval(intervalMs, callback) {
    const intervalTicks = this.msToTicks(intervalMs);
    const id2 = this.nextId++;
    const nextTick = this.world.loop.currentTick + intervalTicks;
    this.intervals.set(id2, { intervalTicks, nextTick, callback });
    return id2;
  }
  clearInterval(id2) {
    this.intervals.delete(id2);
  }
  get currentTick() {
    return this.world.loop.currentTick;
  }
}
