// src/systems/treeManager.ts
var TREE_BUCKET_SIZE = 16;

class TreeManager {
  world;
  timers;
  trees = new Map;
  spawnPoints = [];
  worldType = "forest";
  onTreeChopped;
  treeBuckets = new Map;
  constructor(world, timers) {
    this.world = world;
    this.timers = timers;
  }
  setOnTreeChopped(callback) {
    this.onTreeChopped = callback;
  }
  setWorldType(type) {
    this.worldType = type;
  }
  addSpawnPoint(point) {
    this.spawnPoints.push(point);
  }
  addSpawnPoints(points) {
    this.spawnPoints.push(...points);
  }
  getGroundY(spawnPointY) {
    return spawnPointY;
  }
  spawnAll() {
    for (const point of this.spawnPoints) {
      this.spawnTree(point);
    }
  }
  spawnSpawnPoints(points) {
    for (const point of points) {
      this.spawnTree(point);
    }
  }
  spawnTree(point) {
    const def = TREES[point.treeId];
    if (!def) {
      console.error(`[TreeManager] Unknown tree: ${point.treeId}`);
      return;
    }
    const groundY = this.getGroundY(point.position.y);
    const { maxHp, powerReward, shardReward } = applyWorldMultipliers(def, this.worldType);
    const entity = new m0({
      name: `Tree-${point.id}`,
      modelUri: def.modelUri,
      modelScale: 1,
      rigidBodyOptions: {
        type: mH.FIXED
      }
    });
    const instance = {
      id: point.id,
      entity,
      debrisEntity: null,
      definition: def,
      currentHp: maxHp,
      maxHp,
      powerReward,
      shardReward,
      position: { x: point.position.x, y: groundY, z: point.position.z },
      groundY,
      isChopped: false
    };
    const bucketKey = this.getBucketKey(instance.position);
    instance.bucketKey = bucketKey;
    this.trees.set(point.id, instance);
    this.addTreeToBucket(point.id, bucketKey);
    entity.__treeId = point.id;
    entity.spawn(this.world, { x: point.position.x, y: groundY, z: point.position.z });
  }
  damageTree(treeId, damage, player) {
    const tree = this.trees.get(treeId);
    if (!tree || tree.isChopped || !tree.entity)
      return false;
    tree.currentHp -= damage;
    new LV({
      uri: "audio/sfx/damage/hit-wood.mp3",
      volume: 0.25,
      referenceDistance: 6,
      position: tree.position
    }).play(this.world);
    tree.entity.setTintColor({ r: 1, g: 0.8, b: 0.8 });
    setTimeout(() => {
      if (tree.entity?.isSpawned) {
        tree.entity.setTintColor(undefined);
      }
    }, 100);
    if (tree.currentHp <= 0) {
      this.chopTree(tree, player);
      return true;
    }
    return false;
  }
  chopTree(tree, player) {
    tree.isChopped = true;
    awardTreeChopRewards(player, tree.powerReward, tree.shardReward);
    new LV({
      uri: "audio/sfx/damage/hit-woodbreak.mp3",
      volume: 0.35,
      referenceDistance: 8,
      position: tree.position
    }).play(this.world);
    if (this.onTreeChopped) {
      this.onTreeChopped(tree, player);
    }
    if (tree.entity?.isSpawned) {
      tree.entity.setOpacity(0);
      const entityToDespawn = tree.entity;
      setTimeout(() => {
        if (entityToDespawn.isSpawned)
          entityToDespawn.despawn();
      }, 150);
    }
    tree.entity = null;
    this.spawnDebris(tree);
    const respawnMs = tree.definition.respawnSeconds * 1000;
    this.timers.setTimeout(respawnMs, () => {
      this.respawnTree(tree.id);
    });
  }
  spawnDebris(tree) {
    const debris = getRandomDebris();
    const debrisEntity = new m0({
      name: `Debris-${tree.id}`,
      modelUri: debris.modelUri,
      modelScale: 1
    });
    tree.debrisEntity = debrisEntity;
    debrisEntity.spawn(this.world, tree.position);
    this.animateDebrisFade(debrisEntity);
  }
  animateDebrisFade(entity) {
    const fadeDurationMs = 1000;
    const frameInterval = 50;
    let elapsed = 0;
    const fadeLoop = () => {
      elapsed += frameInterval;
      if (!entity.isSpawned) {
        return;
      }
      const progress = Math.min(1, elapsed / fadeDurationMs);
      const opacity = 1 - progress;
      entity.setOpacity(opacity);
      if (elapsed >= fadeDurationMs) {
        if (entity.isSpawned) {
          entity.despawn();
        }
      } else {
        setTimeout(fadeLoop, frameInterval);
      }
    };
    setTimeout(fadeLoop, frameInterval);
  }
  respawnTree(treeId) {
    const tree = this.trees.get(treeId);
    if (!tree)
      return;
    if (tree.debrisEntity?.isSpawned) {
      tree.debrisEntity.despawn();
    }
    tree.debrisEntity = null;
    const point = this.spawnPoints.find((p) => p.id === treeId);
    if (!point)
      return;
    this.removeTreeFromBucket(treeId, tree.bucketKey);
    this.trees.delete(treeId);
    this.spawnTree(point);
  }
  getTreeByEntity(entity) {
    const treeId = entity.__treeId;
    return treeId ? this.trees.get(treeId) : undefined;
  }
  getTree(treeId) {
    return this.trees.get(treeId);
  }
  getAllTrees() {
    return Array.from(this.trees.values()).filter((t3) => !t3.isChopped);
  }
  getTreesInRadius(center, radius) {
    const radiusSq = radius * radius;
    const result = [];
    const visited = new Set;
    const bucketKeys = this.getBucketKeysForRadius(center, radius);
    for (const key of bucketKeys) {
      const bucket = this.treeBuckets.get(key);
      if (!bucket)
        continue;
      for (const treeId of bucket) {
        if (visited.has(treeId))
          continue;
        visited.add(treeId);
        const tree = this.trees.get(treeId);
        if (!tree || tree.isChopped)
          continue;
        const dx2 = tree.position.x - center.x;
        const dz2 = tree.position.z - center.z;
        const distSq = dx2 * dx2 + dz2 * dz2;
        if (distSq <= radiusSq) {
          result.push(tree);
        }
      }
    }
    return result;
  }
  cleanup() {
    for (const tree of this.trees.values()) {
      if (tree.entity?.isSpawned) {
        tree.entity.despawn();
      }
      if (tree.debrisEntity?.isSpawned) {
        tree.debrisEntity.despawn();
      }
    }
    this.trees.clear();
    this.treeBuckets.clear();
  }
  getBucketKey(position) {
    const xIndex = Math.floor(position.x / TREE_BUCKET_SIZE);
    const zIndex = Math.floor(position.z / TREE_BUCKET_SIZE);
    return `${xIndex}|${zIndex}`;
  }
  getBucketKeysForRadius(center, radius) {
    const minX = Math.floor((center.x - radius) / TREE_BUCKET_SIZE);
    const maxX = Math.floor((center.x + radius) / TREE_BUCKET_SIZE);
    const minZ = Math.floor((center.z - radius) / TREE_BUCKET_SIZE);
    const maxZ = Math.floor((center.z + radius) / TREE_BUCKET_SIZE);
    const keys = [];
    for (let x = minX;x <= maxX; x++) {
      for (let z = minZ;z <= maxZ; z++) {
        keys.push(`${x}|${z}`);
      }
    }
    return keys;
  }
  addTreeToBucket(treeId, bucketKey) {
    if (!this.treeBuckets.has(bucketKey)) {
      this.treeBuckets.set(bucketKey, new Set);
    }
    this.treeBuckets.get(bucketKey).add(treeId);
  }
  removeTreeFromBucket(treeId, bucketKey) {
    const key = bucketKey ?? this.trees.get(treeId)?.bucketKey;
    if (!key)
      return;
    const bucket = this.treeBuckets.get(key);
    if (!bucket)
      return;
    bucket.delete(treeId);
    if (bucket.size === 0) {
      this.treeBuckets.delete(key);
    }
  }
}
